window.RXA.push(
/* ===== EMERGÊNCIAS ALÉRGICAS / TRAUMA / FERIMENTOS ===== */
{n:'Anafilaxia',cid:'T78.2',sp:'Emergência',ps:[{v:'IM / EV / INALATÓRIO',i:['ADRENALINA 1 mg/mL (1:1.000) 0,5 mg (0,5 mL) IM na face ANTEROLATERAL DA COXA (vasto lateral) IMEDIATAMENTE — 0,01 mg/kg; repetir a cada 5–15 min se sem melhora (até 3 doses). Não há contraindicação absoluta. Não aplicar SC nem EV em bolus fora da PCR','Decúbito dorsal com pernas elevadas (não sentar/levantar bruscamente — "síndrome do ventrículo vazio"); gestante em decúbito lateral esquerdo; se dispneia, semi-sentado','O₂ 10–15 L/min em máscara não reinalante; 2 acessos calibrosos; SF 0,9% 1–2 L EV rápido (20 mL/kg) se hipotensão — repetir','Broncoespasmo persistente: salbutamol 4–8 jatos com espaçador ou nebulização (fenoterol 10 gotas) a cada 20 min','Refratária após 2–3 doses IM: adrenalina EV em infusão 0,05–0,1 mcg/kg/min (1 mg em 100 mL SF = 10 mcg/mL → 20–60 mL/h) com monitor; glucagon 1–5 mg EV em 5 min se betabloqueador; noradrenalina/vasopressina se choque refratário; via aérea precoce se edema de laringe (rouquidão, estridor) — IOT difícil, preparar cricotireoidostomia','ADJUVANTES (não substituem adrenalina; não previnem obstrução/choque): hidrocortisona 200 mg EV ou metilprednisolona 1–2 mg/kg (evidência fraca para prevenir reação bifásica — opcional); prometazina 50 mg IM / difenidramina 50 mg EV (prurido/urticária); ranitidina/famotidina 20 mg EV (anti-H2)','Observação mínima 4–6 h após resolução (reação bifásica em 5–20%, até 72 h); 12–24 h se grave, repetida adrenalina, asma, história de bifásica, ou acesso difícil ao PS','Triptase sérica em 1–3 h do início (confirma; comparar com basal); identificar o gatilho (alimento, veneno de himenóptero, medicamento — AINE, betalactâmico, contraste, relaxante muscular)']}],casa:[{v:'USO ORAL',i:[['Prednisona 20 mg','6 comprimidos','Tomar 2 comprimidos (40 mg) pela manhã por 3 dias (opcional — prevenção de reação tardia/urticária)'],['Loratadina 10 mg (ou fexofenadina 180 mg / cetirizina 10 mg)','6 comprimidos','Tomar 1 comprimido de 12/12 h por 3 dias, depois 1×/dia se prurido'],['Famotidina 20 mg (opcional, anti-H2)','6 comprimidos','Tomar 1 comprimido de 12/12 h por 3 dias']]},{v:'USO INTRAMUSCULAR — AUTOAPLICAÇÃO DE EMERGÊNCIA',i:[['Adrenalina autoinjetor 0,3 mg (EpiPen®/Anapen® — importado) OU, se indisponível: Adrenalina 1 mg/mL ampola 1 mL + seringa de 1 mL com agulha 25×7 (preparar/orientar; validade curta fora da ampola)','2 unidades','Aplicar 0,3–0,5 mg (0,3–0,5 mL) IM na face lateral da coxa aos primeiros sinais de reação grave (falta de ar, inchaço de garganta, tontura, vômitos após exposição); repetir em 5–15 min se não melhorar; chamar o SAMU 192 e ir ao PS mesmo que melhore']]}],ori:['Entregar PLANO DE AÇÃO escrito: reconhecer sinais, usar adrenalina primeiro (anti-histamínico não trata anafilaxia), deitar com pernas elevadas, chamar 192; ensinar a família a aplicar','Evitar estritamente o gatilho identificado; ler rótulos; informar alergia em todos os atendimentos (bracelete/cartão); se medicamentoso — registrar o nome e evitar classe cruzada','Encaminhar ao alergista/imunologista (investigação, imunoterapia com veneno de himenóptero — eficácia > 95%)','Revisar betabloqueadores/IECA (pioram gravidade e resposta à adrenalina) com o médico assistente; asma deve estar bem controlada (↑ risco de morte)','Reação a alimento: anafilaxia induzida por exercício pós-prandial (evitar exercício 4 h após a refeição); contaminação cruzada'],al:['Sinais de recorrência nas próximas 72 h: urticária generalizada, inchaço de lábios/língua/garganta, rouquidão, chiado, falta de ar, dor abdominal/vômitos, tontura/desmaio → aplicar adrenalina e SAMU 192 imediatamente'],ref:'WAO Anaphylaxis Guidance 2020 (Cardona); EAACI 2021 (Muraro); AAAAI/ACAAI Practice Parameter 2020/2023 (Shaker — corticoide/anti-H1 não previnem bifásica); ASBAI 2021 (Guia Brasileiro de Anafilaxia); Resuscitation Council UK 2021.'},
{n:'Ferimento cortocontuso / laceração (sutura)',cid:'T14.1 / S01 / S61',sp:'Cirurgia',ps:[{v:'PROCEDIMENTO / VO / IM',i:['Analgesia: dipirona 1 g VO/EV; anestesia local: lidocaína 2% sem vasoconstritor (máx. 4,5 mg/kg ≈ 15 mL em 70 kg) ou com adrenalina 1:200.000 (máx. 7 mg/kg; segura em dedos/nariz/orelha segundo evidência atual — evitar em isquemia/vasculopatia); bloqueio digital (sem vaso) em dedos; tamponar com lidocaína + bicarbonato 1:10 ↓ dor','Limpeza: irrigação abundante com SF 0,9% (ou água potável — equivalente, Cochrane) sob pressão (seringa 20–60 mL + agulha 18–19 G), 50–100 mL/cm; remover corpos estranhos e tecido desvitalizado (debridamento econômico); não usar iodo/água oxigenada/clorexidina dentro da ferida (citotóxicos); explorar tendões/nervos/vasos e movimentos','Fechamento primário: até 12–18 h (face/couro cabeludo até 24 h) se limpa; mordedura, > 18 h, muito contaminada, esmagamento, perfurante profunda, imunossuprimido → considerar fechamento tardio (3–5 d) ou cicatrização por 2ª intenção','Fio: face mononáilon 5-0/6-0 (retirar 5–7 d); couro cabeludo 3-0/4-0 ou grampos (7–10 d); tronco/MMSS 4-0 (7–10 d); MMII/áreas de tensão 3-0/4-0 (10–14 d); palma/planta 3-0/4-0 (14 d); mucosa oral categute/vicryl 4-0 (absorvível); lacerações pequenas e sem tensão: cola (cianoacrilato) ou fita adesiva','Curativo oclusivo seco por 24–48 h; imobilizar se sobre articulação; RX se suspeita de fratura, vidro, metal ou corpo estranho radiopaco; USG se vegetal/madeira','ANTIBIÓTICO PROFILÁTICO não é rotina em laceração simples; indicar (cefalexina) se: mordedura, contaminação grosseira, fratura exposta, exposição de tendão/osso/articulação, mão com lesão extensa, imunossuprimido/diabético/vasculopata, lesão intraoral through-and-through','PROFILAXIA DO TÉTANO: ver protocolo "Profilaxia antitetânica"']}],casa:[{v:'USO ORAL',i:[['Dipirona 500 mg (ou paracetamol 750 mg)','10 comprimidos','Tomar 1 comprimido de 6/6 h se dor'],['Ibuprofeno 600 mg (se dor moderada; evitar se sangramento ativo)','9 comprimidos','Tomar 1 comprimido de 8/8 h após refeições por 3 dias se necessário'],['Cefalexina 500 mg (SOMENTE se indicação de profilaxia — ver acima)','20 cápsulas','Tomar 1 cápsula de 6/6 h por 5 dias']]},{v:'USO TÓPICO / CURATIVO',i:[['Gaze estéril, micropore e soro fisiológico 0,9% (ou água e sabão)','1 pacote / 1 frasco','Trocar o curativo 1×/dia após o 1º dia: lavar com SF ou água e sabão neutro, secar, cobrir com gaze seca; não usar pomadas com antibiótico de rotina (sem benefício, dermatite)'],['Vaselina sólida / petrolato (face — manter úmido após 48 h)','1 bisnaga','Aplicar fina camada 2×/dia sobre a sutura na face após 48 h (↑ cicatrização, igual à pomada antibiótica)']]}],ori:['Manter o curativo seco e limpo por 24–48 h; depois pode molhar no banho (água corrente e sabão), secar com toque e cobrir; não mergulhar (piscina/mar/banheira) até retirar os pontos','Retirar os pontos no dia indicado: face 5–7 dias; couro cabeludo 7–10; tronco/braços 7–10; pernas/mãos/articulações 10–14; não arrancar crostas; elevar o membro nas primeiras 48 h','Protetor solar FPS ≥ 30 na cicatriz por 6–12 meses após retirar os pontos (↓ hiperpigmentação); cicatriz amadurece em 6–12 meses','Retorno em 48–72 h para revisão (ou antes se sinais de infecção); se foi fechamento tardio, retorno em 3–5 dias para suturar','Tétano: anotar a data da dose e completar o esquema (3 doses) na UBS se incompleto'],al:['Vermelhidão que se espalha, calor, pus, dor crescente após 48 h, febre, estrias vermelhas (infecção — abrir pontos, cultura, antibiótico)','Sangramento que não para com compressão de 15 min, deiscência (abertura da ferida)','Dormência, fraqueza, dificuldade de mover dedos/membro (lesão de nervo/tendão não detectada), dor desproporcional/edema tenso (compartimental)','Trismo, rigidez de nuca/mandíbula, espasmos (tétano — raro mas grave)'],ref:'Forsch AFP 2017 (laceração); Cochrane 2022 (água × SF — Fernandez); Cochrane 2013 (cola); Prabhakar 2017 (lidocaína com adrenalina em dedos — segura); IDSA SSTI 2014; MS — Manual de Profilaxia do Tétano; ACEP; Zehtabchi 2012 (antibiótico profilático sem benefício em lacerações simples).'},
{n:'Profilaxia antitetânica (ferimentos)',cid:'Z23 / Z29.1',sp:'Cirurgia',ps:[{v:'IM (sítios diferentes para vacina e imunoglobulina)',i:['Classificar o ferimento: BAIXO RISCO (limpo, superficial, < 6 h, sem corpo estranho/tecido desvitalizado) × ALTO RISCO (sujo/contaminado por terra, fezes, saliva; profundo/perfurante; queimadura; esmagamento; congelamento; > 6 h; corpo estranho; fratura exposta; mordedura; necrose; projétil; úlceras crônicas; usuário de drogas injetáveis)','HISTÓRIA VACINAL ≥ 3 doses — última dose < 5 anos: NADA (em ambos); 5–10 anos: baixo risco → nada / alto risco → 1 dose de dT (reforço); > 10 anos: dT em ambos (alto risco: dT; imunoglobulina só se imunossuprimido/desnutrido grave/idoso frágil/ferimento muito extenso ou de difícil limpeza)','HISTÓRIA VACINAL incerta ou < 3 doses: baixo risco → dT (iniciar/completar esquema: 3 doses 0-2-4 meses ou 0-1-6) / alto risco → dT + IMUNOGLOBULINA ANTITETÂNICA humana (IGHAT) 250 UI IM (500 UI se > 24 h, > 90 kg, queimadura extensa, ferimento de alto risco muito contaminado) em outro sítio; se IGHAT indisponível: soro antitetânico (SAT) 5.000 UI IM após teste/precauções de anafilaxia','dT (dupla adulto) 0,5 mL IM deltoide — ou dTpa (preferível se gestante ≥ 20 sem, profissional de saúde, contato de RN, ou nunca recebeu dTpa — SBIm); vacinar mesmo gestante','Limpeza/desbridamento da ferida é a medida mais importante; não há "janela" — tétano tem incubação de 3–21 dias: vacinar/IG mesmo dias depois','Imunossuprimido, HIV, > 65 anos frágil, desnutrido grave: considerar IGHAT em ferimento de alto risco independentemente do esquema','Registrar no cartão de vacina; agendar as doses seguintes na UBS']}],casa:[{v:'ESQUEMA A COMPLETAR NA UBS',i:[['Vacina dT (ou dTpa) — se esquema incompleto/desconhecido','3 doses','1ª dose hoje (no PS); 2ª dose em 2 meses (mínimo 30 dias); 3ª dose em 4–6 meses após a 1ª; reforço a cada 10 anos (ou 5 anos se novo ferimento de risco)'],['Vacina dT — se já tinha 3 doses e só precisou de reforço','1 dose (hoje)','Próximo reforço em 10 anos (anotar no cartão)']]},{v:'USO ORAL',i:[['Dipirona 500 mg','5 comprimidos','Tomar 1 comprimido de 6/6 h se dor no local da vacina/ferimento']]}],ori:['Guardar o comprovante e levar à UBS para registrar e agendar as próximas doses — esquema incompleto não protege','Dor/vermelhidão no local da vacina por 1–3 dias é normal (compressa fria); nódulo pode durar semanas','Cuidados com a ferida: lavar com água e sabão diariamente, retirar sujeira visível, observar sinais de infecção','Tétano não confere imunidade: quem já teve precisa vacinar; esquema é válido para a vida se reforçado a cada 10 anos','Gestantes: dTpa a cada gestação a partir de 20 semanas (protege o RN contra coqueluche)'],al:['Trismo (dificuldade de abrir a boca), rigidez de nuca/abdome, espasmos musculares dolorosos, dificuldade para engolir, "riso sardônico" — em até 3 semanas após ferimento → PS imediatamente (tétano = UTI)','Reação alérgica grave após vacina/soro: urticária generalizada, falta de ar, edema de face → PS','Sinais de infecção da ferida'],ref:'MS — Guia de Vigilância em Saúde 2024 (Tétano acidental — Quadro de condutas profiláticas); Manual dos CRIE 2023; CDC/ACIP 2020 (Tdap/Td e TIG); SBIm 2024; OMS 2017 (Tetanus vaccines position paper).'},
{n:'Mordedura de cão / gato / humana',cid:'W54 / W55 / W50 / T14.1',sp:'Cirurgia',ps:[{v:'PROCEDIMENTO / VO / IM',i:['Lavar IMEDIATA e abundantemente com água corrente e sabão por 15 min (↓ risco de raiva e infecção); irrigar com SF sob pressão; desbridar tecido desvitalizado; explorar (tendão, articulação, osso — mão!); RX se suspeita de fratura/dente retido/articulação','Fechamento: NÃO suturar primariamente mordeduras de mão/pé, punctórias profundas (gato), > 12 h (face > 24 h), esmagamento, em imunossuprimido ou com sinais de infecção → deixar aberta/fechamento tardio; face/couro cabeludo e lacerações amplas em outros locais (< 12 h, bem lavadas) podem ser suturadas frouxamente (estética — evidência de que infecção não aumenta muito)','ANTIBIÓTICO PROFILÁTICO (3–5 dias) — amoxicilina-clavulanato (cobre Pasteurella, Capnocytophaga, anaeróbios, S. aureus, Eikenella em humana): indicado em TODA mordedura de gato, mordeduras de mão/pé/face/genital, profundas/punctórias, com esmagamento, próximas a osso/articulação/prótese, que precisaram de desbridamento/sutura, em imunossuprimido/diabético/asplênico/hepatopata/edema crônico do membro; mordedura humana (soco em dente = "fight bite" → tratar como ferida séptica articular, ortopedia)','Já infectada (dor, edema, pus, febre — gato em 12–24 h, cão 24–72 h): cultura, amoxicilina-clavulanato 875/125 12/12 h 10–14 d VO; sistêmica/mão/osso → internar: ampicilina-sulbactam 3 g EV 6/6 h ou ceftriaxona + metronidazol; tenossinovite/artrite → cirurgia','PROFILAXIA DA RAIVA (MS 2022): cão/gato SAUDÁVEL e OBSERVÁVEL (10 dias): não iniciar; observar — se adoecer/morrer/desaparecer: iniciar. Cão/gato SUSPEITO/RAIVOSO/DESAPARECIDO/SILVESTRE/MORCEGO (qualquer contato): acidente LEVE (único, superficial, tronco/membros, exceto mãos/pés) → vacina 4 doses IM (dias 0, 3, 7, 14); acidente GRAVE (cabeça/face/pescoço/mãos/pés, múltiplos, profundos, lambedura de mucosa, morcego) → SORO antirrábico 40 UI/kg (ou imunoglobulina humana 20 UI/kg) infiltrado na lesão (restante IM) + vacina dias 0, 3, 7, 14; previamente vacinado completo: 2 doses (0 e 3) sem soro. Morcego: sempre tratar como grave','PROFILAXIA DO TÉTANO conforme protocolo (mordedura = alto risco)','Humana: avaliar hepatite B (vacina ± IGHAHB), HIV (PEP se risco — sangue visível), hepatite C (sorologia basal e 3–6 meses) no mordido e, se possível, no agressor','Elevar o membro; imobilizar a mão; dipirona 1 g; notificar (SINAN — acidente por animal potencialmente transmissor de raiva); comunicar vigilância para observar o animal']}],casa:[{v:'USO ORAL',i:[['Amoxicilina + clavulanato 875/125 mg — profilaxia','10 comprimidos (profilaxia 3–5 d) / 28 (tratamento 10–14 d)','Tomar 1 comprimido de 12/12 h, às refeições, por 3–5 dias (profilaxia) ou 10–14 dias se já infectada'],['OU Doxiciclina 100 mg 12/12 h + Metronidazol 400 mg 8/8 h (alergia a penicilina; gestante: clindamicina 300 mg 6/6 h + SMX-TMP ou cefuroxima + metronidazol)','—','Pelo mesmo período (não usar cefalexina/eritromicina/clindamicina isoladas — não cobrem Pasteurella)'],['Dipirona 500 mg ou Paracetamol 750 mg','10 comprimidos','Tomar 1 comprimido de 6/6 h se dor'],['Ibuprofeno 600 mg','9 comprimidos','Tomar 1 comprimido de 8/8 h por 3 dias se dor/edema']]},{v:'VACINAÇÃO (UBS/PS — conforme avaliação)',i:[['Vacina antirrábica (cultivo celular) — se indicada','4 doses IM (deltoide; nunca glúteo)','Dias 0, 3, 7 e 14 — NÃO atrasar; se já vacinado anteriormente com esquema completo: dias 0 e 3'],['Soro antirrábico heterólogo 40 UI/kg ou IG humana 20 UI/kg — se acidente grave','dose única','Infiltrar o máximo possível ao redor/dentro das lesões no dia 0 (até o 7º dia da 1ª dose de vacina), restante IM'],['Vacina dT (tétano) — se indicada','1 dose + completar esquema','Conforme protocolo de tétano']]}],ori:['Manter a ferida aberta limpa: lavar com água e sabão 2×/dia, cobrir com gaze; elevar a mão/membro acima do coração; imobilizar a mão se envolvida','Retorno OBRIGATÓRIO em 24–48 h para reavaliar infecção (gato: Pasteurella em < 24 h) e, se ferida deixada aberta, avaliar fechamento tardio em 3–5 dias','Observar o animal por 10 dias (cão/gato): se adoecer, morrer, fugir ou mudar comportamento, retornar IMEDIATAMENTE para iniciar/completar profilaxia da raiva; não matar o animal (se morrer, encaminhar a cabeça para análise via vigilância)','Completar TODAS as doses da vacina antirrábica nas datas certas — raiva é 100% letal e 100% prevenível; comparecer à UBS para dT','Prevenção: não se aproximar de animais desconhecidos/morcegos; vacinar cães e gatos'],al:['Vermelhidão, calor, inchaço rápido, pus, dor intensa, febre, gânglios, estrias vermelhas (infecção — Pasteurella é rápida)','Dificuldade/dor para mover dedos, dedo em flexão com dor à extensão passiva (tenossinovite/artrite séptica) → cirurgia urgente','Febre, mal-estar, confusão em asplênico/cirrótico/etilista (Capnocytophaga — sepse fulminante)','Formigamento/dor no local da mordida semanas depois, febre, ansiedade, dificuldade para engolir água, agitação (raiva — emergência)'],ref:'MS — Protocolo de Tratamento da Raiva Humana e Nota Técnica 8/2022 (esquema 4 doses 0-3-7-14); OMS Rabies Position Paper 2018; IDSA SSTI 2014 (Stevens); Cochrane 2019 (antibiótico profilático — benefício em mão/gato); Medeiros Cochrane 2001; Ellis AFP 2014; Paschos Injury 2014 (sutura primária).'},
{n:'Queimadura leve (1º e 2º grau superficial, pequena extensão)',cid:'T30.0 / T30.2',sp:'Cirurgia',ps:[{v:'PROCEDIMENTO / VO / IM',i:['Resfriar com ÁGUA CORRENTE fria (não gelada, 15–25 °C) por 20 min — eficaz até 3 h após (↓ profundidade e necessidade de enxerto); nunca gelo, pasta de dente, manteiga, café, clara de ovo; retirar anéis/relógio/roupas não aderidas','Estimar SCQ (regra dos 9 / palma do paciente com dedos = 1%) e profundidade: 1º grau (eritema, sem bolha, dói) · 2º superficial (bolha, úmida, rósea, muito dolorosa, enche capilar) · 2º profunda (branca/vermelha moteada, seca, pouca dor) · 3º (branca/parda/carbonizada, indolor, coriácea)','AMBULATORIAL (ABA/SBQ): 2º grau < 10% SCQ (adulto) sem face/mãos/pés/genitais/períneo/articulações/circunferencial, sem inalação, sem elétrica/química, sem comorbidade descompensada — fora disso → referir à unidade de queimados','Analgesia ANTES do curativo: dipirona 1–2 g EV + cetoprofeno 100 mg EV; dor intensa: morfina 2–4 mg EV titulada / tramadol 100 mg EV; cetamina 0,25–0,5 mg/kg EV para troca de curativo extensa','Limpeza: água e sabão neutro/clorexidina 0,2% aquosa ou SF; bolhas: manter íntegras pequenas (< 6 mm, curativo protetor); romper/desbridar as grandes, tensas, sobre articulação ou rotas (teto desvitalizado é meio de cultura) — prática variável; evidência de baixa qualidade','Curativo: 1º grau → sem cobertura, hidratante/aloe vera; 2º grau → cobertura não aderente (gaze vaselinada/rayon + gaze seca, trocar a cada 24–48 h) OU hidrocoloide/filme de poliuretano/espuma com prata (troca a cada 3–7 dias — menos dor, cicatrização mais rápida que sulfadiazina — Cochrane 2013); SULFADIAZINA DE PRATA 1%: ainda amplamente usada no SUS (fina camada + gaze, trocar 1–2×/dia), mas atrasa cicatrização em superficiais e dificulta avaliar a profundidade — evitar na face, em gestantes/RN e nas superficiais; face: só vaselina/neomicina leve e limpeza frequente, sem oclusão','NÃO usar antibiótico sistêmico profilático (sem benefício, ↑ resistência); tétano conforme protocolo (queimadura = alto risco); elevar o membro','Química: irrigação copiosa 30–60 min (não neutralizar); olhos: lavar 30 min + oftalmo; elétrica: ECG, CK, urina (mioglobina) → geralmente internar; circunferencial: avaliar perfusão (escarotomia)']}],casa:[{v:'USO ORAL',i:[['Dipirona 1 g (ou 500 mg)','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor (tomar 30–60 min antes da troca do curativo)'],['Ibuprofeno 600 mg (ou naproxeno 500 mg 12/12 h)','15 comprimidos','Tomar 1 comprimido de 8/8 h após refeições por 3–5 dias'],['Tramadol 50 mg (resgate — dor intensa, troca de curativo)','10 cápsulas','Tomar 1 cápsula 30 min antes do curativo ou de 8/8 h se dor forte, por até 5 dias'],['Loratadina 10 mg ou Hidroxizina 25 mg à noite (prurido na cicatrização)','10 comprimidos','Tomar 1 comprimido 1×/dia se coceira']]},{v:'USO TÓPICO / CURATIVO',i:[['Curativo não aderente: gaze de rayon ou vaselinada (ou placa de hidrocoloide/espuma) + gaze seca + atadura/micropore','conforme área','Trocar a cada 24–48 h (gaze vaselinada) ou a cada 3–5 dias (hidrocoloide), ou quando saturado; lavar com água corrente e sabão neutro antes de recolocar'],['OU Sulfadiazina de prata 1% creme (se orientado — não na face; 2º grau profundo/áreas sujas)','1 bisnaga','Lavar a área com água e sabão, secar, aplicar camada de 2–3 mm e cobrir com gaze; trocar 1×/dia (2× se muito exsudato) por até 7–10 dias; retirar bem o creme anterior'],['Hidratante sem perfume (ureia 5–10%/óleo de amêndoas) ou aloe vera — 1º grau e após epitelização','1 frasco','Aplicar 3–4×/dia'],['Protetor solar FPS ≥ 50 (após cicatrizar)','1 frasco','Aplicar diariamente na área por 12 meses; evitar sol direto']]}],ori:['Resfriar queimaduras futuras com água corrente fria por 20 min; não passar nada "caseiro" (pasta de dente, manteiga, café, pó de café, clara de ovo, pomadas sem orientação)','Trocar o curativo conforme orientado; lavar as mãos antes; se a gaze grudar, umedecer com SF/água para soltar sem machucar; não estourar bolhas em casa','Elevar o membro queimado acima do coração nas primeiras 48–72 h (↓ edema e dor); mexer dedos/articulações várias vezes ao dia para não enrijecer','Beber bastante líquido e alimentação rica em proteína; evitar fumar (↓ cicatrização)','Retorno em 48–72 h para reavaliar profundidade (2º grau pode aprofundar em 24–72 h) e depois a cada 3–7 dias até epitelizar (2º superficial: 7–14 dias); se não cicatrizou em 14–21 dias → unidade de queimados (enxerto)','Após cicatrizar: hidratar, massagear, protetor solar por 1 ano, malha compressiva se cicatriz hipertrófica (fisioterapia)'],al:['Febre, pus, mau cheiro, vermelhidão/calor que avança para além da queimadura, piora da dor após o 2º–3º dia (infecção — celulite/sepse)','Área que fica branca/escura, perde a sensibilidade ou não melhora (aprofundamento → avaliação para enxerto)','Dedos/mão/pé frios, roxos, dormentes, dor intensa (queimadura circunferencial — síndrome compartimental)','Náuseas, vômitos, febre alta, rash, diarreia, confusão (síndrome do choque tóxico — rara, criança)','Dificuldade para respirar, rouquidão (inalação) — mesmo horas depois'],ref:'ISBI Practice Guidelines 2016/2018; ABA Burn Center Referral Criteria 2022; Cochrane 2013 (Wasiak — curativos; hidrocoloide/prata nanocristalina > sulfadiazina) e 2017 (antibiótico profilático sem benefício); Griffin Ann Emerg Med 2020 (água fria 20 min); SBQ — Diretrizes 2018; Queensland Burns Guidelines 2023; MS — Cartilha para Tratamento de Emergência das Queimaduras 2012.'},
{n:'Picada de escorpião / aranha / abelha (acidentes com animais peçonhentos)',cid:'T63.2 / T63.3 / T63.4 / X23',sp:'Emergência',ps:[{v:'LOCAL / VO / EV / SORO',i:['ESCORPIÃO (Tityus): classificar — LEVE (dor local, parestesia, eritema, sudorese local): analgesia + observação 6–12 h; MODERADO (dor intensa + sudorese profusa, vômitos, taquicardia, agitação, hipertensão leve, salivação): soro antiescorpiônico (SAEsc) 2–3 ampolas EV + observação 12–24 h; GRAVE (vômitos incoercíveis, sudorese profusa, bradicardia, hipotensão/choque, IC/edema pulmonar, convulsão, coma): SAEsc 4–6 ampolas EV em 20–30 min + UTI; crianças < 7 anos e idosos: evoluem rápido → soro em moderado sempre, observar leve por 12 h. Soro em até 2 h (ideal) — diluir em SF 100 mL, sem teste cutâneo, pré-medicação opcional; ECG, glicemia, amilase','Dor local (escorpião/aranha): infiltração de lidocaína 2% SEM vasoconstritor 1–2 mL (bloqueio troncular se dedo) — repetir até 3× a cada 30–60 min; compressa morna; dipirona 1 g EV ± tramadol 100 mg EV; não fazer torniquete, não cortar, não sugar, não gelo (escorpião)','ARANHA — Phoneutria (armadeira: dor imediata intensa, edema, sudorese, priapismo, choque em criança): lidocaína local + analgesia; soro antiaracnídico (SAAr) 2–4 ampolas (moderado) / 5–10 (grave). Loxosceles (aranha-marrom: picada indolor, após 12–36 h dor, placa marmórea/livedoide → necrose; forma cutâneo-visceral com hemólise, hemoglobinúria, IRA): soro antiloxoscélico/SAAr 5 ampolas (cutânea moderada/grave) ou 10 (visceral) em até 48–72 h + prednisona 40 mg/dia 5 dias; Latrodectus (viúva-negra: dor, contraturas, sudorese, hipertensão, "fácies latrodectísmica"): soro antilatrodéctico 1–2 ampolas IM; gluconato de cálcio 10% 10–20 mL EV lento; BZD para contraturas','ABELHA/VESPA — poucas picadas: remover o ferrão raspando (lâmina/cartão), gelo, anti-H1 (loratadina 10 mg), dipirona, corticoide tópico; ANAFILAXIA (pode ocorrer com 1 picada): adrenalina IM 0,5 mg — ver protocolo; ATAQUE MASSIVO (> 50–100 picadas → envenenamento: hemólise, rabdomiólise, IRA, hepatotoxicidade): internar, hidratação vigorosa, monitorar CK/K/creatinina, soro antiapílico (Apilic — disponível em centros, 2024)','LACRAIA (centopeia): dor local, lidocaína; CARAMUJO/LAGARTA (Lonomia — hemorragia): soro antilonômico; TATURANA comum: compressa fria, anti-H1','Notificar (SINAN — acidente por animal peçonhento, compulsória); tétano conforme protocolo (escorpião/aranha = baixo risco se sem lesão aberta); CIATox 0800 722 6001 para orientação sobre soros/casos']}],casa:[{v:'USO ORAL',i:[['Dipirona 1 g (ou 500 mg)','10 comprimidos','Tomar 1 comprimido de 6/6 h se dor, por 2–3 dias'],['Ibuprofeno 600 mg (abelha/aranha — edema; não na suspeita de dengue)','9 comprimidos','Tomar 1 comprimido de 8/8 h por 3 dias se dor/inchaço'],['Loratadina 10 mg (ou cetirizina 10 mg)','5 comprimidos','Tomar 1 comprimido 1×/dia por 3–5 dias se coceira/inchaço (picadas de inseto)'],['Prednisona 20 mg (Loxosceles cutânea, reação local extensa a himenóptero > 10 cm)','10 comprimidos','Tomar 2 comprimidos (40 mg) pela manhã por 5 dias']]},{v:'USO TÓPICO',i:[['Hidrocortisona 1% creme (ou mometasona 0,1%) — picadas de inseto/reação local','1 bisnaga','Aplicar fina camada no local 2×/dia por 5–7 dias'],['Compressa fria (abelha/vespa) ou morna (escorpião/aranha para dor)','—','15–20 min, 3–4×/dia nas primeiras 48 h']]}],ori:['Escorpião — após alta (observação de 6–12 h sem sintomas sistêmicos): dor pode durar 24–48 h; retornar imediatamente se vômitos, sudorese intensa, agitação, palpitações, falta de ar (principalmente crianças)','Aranha-marrom: a lesão evolui por dias — retorno em 24–48 h e 72 h para reavaliar; curativos; urina escura/icterícia/febre = PS urgente (hemólise)','Prevenção: sacudir roupas/calçados/toalhas, telas em ralos, vedar frestas, não acumular entulho/lixo, luvas ao mexer em madeira/entulho; capturar o animal (sem risco) para identificação','Abelhas: pessoas com reação sistêmica prévia → alergista para imunoterapia (> 95% eficaz) e adrenalina autoinjetável; evitar perfumes/cores vivas; não agitar os braços; afastar-se de enxames','Himenóptero — reação local grande (> 10 cm, 24–48 h) não é alergia sistêmica: não exige adrenalina; anti-H1 + corticoide curto'],al:['Escorpião/aranha: vômitos repetidos, suor frio intenso, salivação, agitação, tremores, palpitações, pressão alta ou baixa, falta de ar, convulsão, priapismo (criança) → PS imediato — soro','Aranha-marrom: mancha que escurece/necrose, bolhas, urina escura ("coca-cola"), icterícia, febre, palidez','Abelha/vespa: urticária generalizada, inchaço de lábios/língua/garganta, rouquidão, chiado, tontura, vômitos, desmaio → anafilaxia (adrenalina + SAMU 192); > 50 picadas → PS para internação mesmo sem sintomas','Qualquer picada: febre, pus, vermelhidão progressiva (infecção secundária)'],ref:'MS — Guia de Vigilância em Saúde 2024 (Acidentes por animais peçonhentos) e Manual de Diagnóstico e Tratamento de Acidentes por Animais Peçonhentos (FUNASA 2001/atualizações); Instituto Butantan/Vital Brazil — bulas dos soros; Isbister Lancet 2011 (escorpião/aranha); Bula Apilic 2024; WAO 2020 (himenópteros); SBToxicologia.'},
/* ===== PSIQUIATRIA / SAÚDE MENTAL ===== */
{n:'Crise de ansiedade / ataque de pânico',cid:'F41.0',sp:'Psiquiatria',ps:[{v:'VO / SL / EV',i:['Primeiro EXCLUIR causa orgânica: glicemia capilar, SatO₂, ECG (arritmia/SCA se > 40 a, dor torácica, fatores de risco), FC/PA, temperatura; TSH, drogas (cocaína/anfetamina/abstinência), hipertireoidismo, TEP (se fatores), asma, feocromocitoma (raro)','Ambiente calmo, acolhimento, explicar que é um ataque de pânico, que não é infarto e que passa em 10–30 min; respiração diafragmática lenta (4 s inspira, 6 s expira; NÃO "saco de papel" — risco em hipoxemia real); técnica de aterramento (5-4-3-2-1)','Se não controlar com medidas não farmacológicas: BENZODIAZEPÍNICO em dose única — clonazepam 0,5–1 mg SL/VO ou diazepam 5–10 mg VO (ou alprazolam 0,5–1 mg); lorazepam 1–2 mg VO (idoso/hepatopata); evitar EV (depressão respiratória) e evitar IM (absorção errática — exceto midazolam)','Agitação intensa/não cooperativo: ver "Agitação psicomotora"; NÃO usar haloperidol para ansiedade pura','Observar 1–2 h; alta com acompanhante (sedação); não dirigir','Avaliar risco de suicídio (perguntar diretamente), uso de álcool/drogas, depressão associada, violência doméstica, luto; se risco → não dar alta sem avaliação psiquiátrica/plano de segurança']}],casa:[{v:'USO ORAL',i:[['ISRS — 1ª linha para transtorno de pânico/ansiedade generalizada (iniciar se recorrente — não é para "crise"): Sertralina 50 mg (ou escitalopram 10 mg / paroxetina 20 mg)','30 comprimidos','Tomar ½ comprimido (25 mg) pela manhã com alimento por 7 dias, depois 1 comprimido (50 mg) 1×/dia; efeito em 2–6 semanas; não interromper; pode piorar a ansiedade na 1ª semana'],['Clonazepam 0,5 mg (ou 2,5 mg/mL gotas: 0,1 mg/gota) — PONTE curta, apenas nas primeiras 2–4 semanas até o ISRS agir, OU resgate raro','10 comprimidos (receita B1 — azul)','Tomar 1 comprimido (ou 5 gotas) SL/VO se crise intensa que não cede com a respiração, no máximo 1×/dia, por até 2–4 semanas; NÃO usar diariamente por mais tempo (dependência); não dirigir/álcool'],['OU Hidroxizina 25 mg (alternativa sem dependência, ansiedade leve/insônia)','20 comprimidos','Tomar 1 comprimido à noite ou de 12/12 h se ansiedade (sonolência)'],['Propranolol 40 mg (sintomas físicos — tremor, palpitação; ansiedade de desempenho; sem asma/bradicardia)','20 comprimidos','Tomar ½–1 comprimido 30–60 min antes de situação desencadeante ou de 12/12 h se palpitações']]}],ori:['Explicar o ciclo do pânico (sintomas físicos → medo → mais sintomas); praticar respiração lenta diariamente (não só na crise); exercício aeróbico regular (30 min/dia — eficácia comparável a medicação leve); sono regular','Reduzir/cortar cafeína, energéticos, nicotina, álcool (abstinência piora), descongestionantes, maconha/estimulantes','Terapia cognitivo-comportamental (TCC) é o tratamento com melhor evidência (igual ou superior a medicação, menos recaída) — encaminhar UBS/CAPS/psicólogo; aplicativos/grupos de apoio','Benzodiazepínico: só uso curto/pontual — risco de dependência, quedas, acidentes, piora cognitiva; não combinar com álcool/opioides; não dar receita longa','Retorno em 2–4 semanas para ajustar o antidepressivo (manter ≥ 6–12 meses após remissão); se pensamentos de morte: CVV 188 (24 h), CAPS, PS'],al:['Dor torácica típica (aperto, irradiação, esforço), dispneia com SatO₂ < 95%, síncope, palpitações irregulares, febre, déficit neurológico, dor de cabeça súbita intensa → investigar causa orgânica','Ideação suicida, plano ou tentativa; alucinações/delírios; uso abusivo de álcool/drogas; crises diárias incapacitantes → psiquiatria/CAPS urgente','Sedação excessiva/confusão com benzodiazepínico (idosos)'],ref:'NICE CG113 (2011/2020) — GAD e pânico; APA Practice Guideline Panic Disorder 2009; Cochrane 2019 (psicoterapias) e 2020 (antidepressivos × BZD); Bandelow WFSBP 2023; ABP — Diretrizes Transtornos de Ansiedade; Canadian Clinical Practice Guidelines (Katzman 2014).'},
{n:'Agitação psicomotora aguda',cid:'R45.1 / F23 / F10.0',sp:'Psiquiatria',ps:[{v:'VO / IM / EV',i:['Segurança da equipe e paciente; retirar objetos perigosos; ambiente calmo; DESESCALADA VERBAL (10 passos — Richmond): 1 interlocutor, tom calmo, respeitar espaço, ofertas simples (água, comida, medicação VO), limites claros — eficaz em grande parte dos casos','SEMPRE buscar causa orgânica (delirium): glicemia capilar, SatO₂, temperatura, PA/FC, pupilas, sinais focais, retenção urinária, dor, hipóxia, hipoglicemia, intoxicação/abstinência (álcool, BZD, cocaína, anticolinérgicos), TCE, infecção (idoso), encefalite, tireoide; ECG (QTc antes de antipsicótico se possível)','VIA ORAL se aceita (preferir sempre): risperidona 2 mg (solução/orodispersível) ou olanzapina 10 mg orodispersível ± lorazepam 2 mg/clonazepam 2 mg; haloperidol 5 mg gotas (2,5–5 mg) + prometazina 25 mg','IM se recusa/risco iminente: HALOPERIDOL 5 mg + PROMETAZINA 50 mg IM (combinação TREC: mais rápida/segura que haloperidol isolado — ↓ distonia; não misturar na mesma seringa é discutível, mas pode) — repetir em 30–60 min se necessário (máx. haloperidol 20 mg/dia); OU olanzapina 10 mg IM (não associar BZD parenteral em 1 h — depressão respiratória); OU midazolam 5–15 mg IM (sedação rápida, 15 min; risco respiratório — monitorar; preferível em intoxicação por estimulantes/abstinência alcoólica/epilepsia)','Casos específicos: ABSTINÊNCIA ALCOÓLICA/BZD → diazepam 10 mg EV/VO (não haloperidol isolado — ↓ limiar convulsivo); INTOXICAÇÃO POR COCAÍNA/ANFETAMINA → benzodiazepínico; DELIRIUM NO IDOSO → tratar causa, haloperidol 0,5–2 mg VO/IM baixa dose, evitar BZD (exceto abstinência); DEMÊNCIA → evitar antipsicótico se possível (↑ mortalidade), baixa dose; GESTANTE → haloperidol baixa dose/prometazina; CETAMINA 4–5 mg/kg IM em agitação extrema/delirium excitado (SAMU) com monitorização','Contenção mecânica: último recurso, 4–5 pontos, prescrita, monitorizada a cada 15–30 min (SatO₂, circulação, posição — nunca pronação/pressão no tórax), tempo mínimo, registrada; sedação associada para reduzir tempo de contenção','Monitorar após medicação: PA, FC, FR, SatO₂, nível de consciência, distonia (biperideno 5 mg IM/EV), acatisia (propranolol/BZD), QTc, síndrome neuroléptica maligna (febre, rigidez, CK↑)','Avaliação psiquiátrica após controle; internação (voluntária/involuntária com comunicação ao MP em 72 h — Lei 10.216) se risco para si/outros']}],casa:[{v:'USO ORAL (após avaliação psiquiátrica — modelo, ajustar pelo diagnóstico)',i:[['Risperidona 2 mg (psicose/mania — ou olanzapina 10 mg / quetiapina 100–300 mg)','30 comprimidos','Tomar 1 comprimido à noite (ajustar 2–6 mg/dia pelo psiquiatra/CAPS)'],['Clonazepam 2 mg (ou lorazepam 2 mg) — curto prazo para agitação/insônia residual','10 comprimidos (receita B1)','Tomar 1 comprimido à noite por 7–14 dias e reavaliar; não dirigir; sem álcool'],['Biperideno 2 mg (se sintomas extrapiramidais com haloperidol)','20 comprimidos','Tomar 1 comprimido de 12/12 h enquanto usar antipsicótico típico'],['Haloperidol 5 mg (alternativa de baixo custo — esquizofrenia/psicose)','30 comprimidos','Tomar 1 comprimido 1–2×/dia conforme orientação']]}],ori:['Alta somente com acompanhante responsável, após sedação revertida e avaliação psiquiátrica/risco; agendar CAPS/psiquiatria em ≤ 7 dias (CAPS acolhe sem agendamento); informar família sobre sinais de recaída','Adesão à medicação de manutenção; evitar álcool/drogas (cannabis e estimulantes precipitam psicose); sono regular; reduzir estressores; família: comunicação não confrontativa, retirar armas/objetos perigosos de casa','Efeitos adversos a observar: rigidez/tremor/torcicolo (distonia — biperideno), inquietação nas pernas (acatisia), sonolência, ganho de peso/glicemia (olanzapina), tontura ao levantar','Lei 10.216/2001: internação involuntária só por laudo médico, comunicada ao MP; preferir CAPS III/leitos em hospital geral','Prevenção de suicídio: CVV 188; plano de segurança escrito; retirar meios letais'],al:['Febre alta + rigidez muscular + confusão + sudorese após antipsicótico (síndrome neuroléptica maligna — PS imediato, suspender, UTI)','Torcicolo/olhos revirados/trismo (distonia aguda — PS para biperideno), dificuldade para engolir','Nova agitação, ideação suicida/homicida, alucinações de comando, recusa alimentar, não dormir por dias','Sonolência extrema, dificuldade respiratória (sedação excessiva, sobretudo com álcool)'],ref:'Richmond West J Emerg Med 2012 (desescalada — BETA Project); TREC trials BMJ 2003/2007 (haloperidol + prometazina); Cochrane 2016/2017 (haloperidol + prometazina; olanzapina IM; midazolam); AAEP Consensus 2012; Garriga WFSBP 2016; ABP — Emergências Psiquiátricas 2020; NICE NG10 2015; Lei 10.216/2001.'},
{n:'Insônia aguda',cid:'G47.0 / F51.0',sp:'Psiquiatria',ps:[{v:'VO',i:['Insônia no PS raramente exige medicação parenteral; identificar causa: dor, dispneia, noctúria, RLS, apneia do sono (ronco, sonolência diurna), depressão/ansiedade, mania (não dorme e não sente falta → não sedar simplesmente), abstinência de álcool/BZD, cafeína/estimulantes/corticoide/betabloqueador, luto/estresse agudo, turnos','Insônia aguda situacional (< 3 meses) com sofrimento importante: pode-se usar hipnótico por POUCOS dias (≤ 2–4 semanas): zolpidem 5–10 mg (5 mg em mulheres/idosos) ou eszopiclona 1–3 mg à noite; evitar iniciar benzodiazepínico (dependência, quedas, cognição); evitar em idosos (Beers)','Se ansiedade/depressão associada: trazodona 50–100 mg à noite (sem dependência; hipotensão) ou mirtazapina 7,5–15 mg (↑ apetite/peso) — melhor que BZD a médio prazo','Idoso/demência: melatonina 2–5 mg 1–2 h antes de dormir, trazodona baixa dose; evitar zolpidem/BZD/anti-H1 sedativos (delirium, quedas)','Não prescrever prometazina/dexclorfeniramina/difenidramina como hipnóticos (anticolinérgicos, tolerância rápida, sonolência residual)','Entregar orientações de higiene do sono e controle de estímulos (ver casa) — a terapia cognitivo-comportamental para insônia (TCC-I) é o tratamento de 1ª linha (superior e mais durável que medicação)']}],casa:[{v:'USO ORAL',i:[['Zolpidem 10 mg (5 mg para mulheres, idosos, hepatopatas) — uso CURTO','7–14 comprimidos (receita B1 — azul)','Tomar 1 comprimido imediatamente antes de deitar (já na cama), somente se necessário, por no máximo 2–4 semanas; não dirigir após; não tomar com álcool; pode causar sonambulismo/amnésia'],['OU Trazodona 50 mg (preferível se humor deprimido/ansiedade, ou uso por mais tempo)','30 comprimidos (receita C1 — branca)','Tomar ½–1 comprimido 30–60 min antes de dormir'],['OU Melatonina 3 mg (idoso, atraso de fase, jet lag)','30 comprimidos','Tomar 1 comprimido 1–2 h antes do horário desejado de dormir, todos os dias, por 4 semanas'],['OU Mirtazapina 15 mg (insônia + depressão + baixo apetite)','30 comprimidos (C1)','Tomar ½–1 comprimido à noite'],['Doxepina 3–6 mg (insônia de manutenção, idoso) — se disponível','30 comprimidos','Tomar 1 comprimido 30 min antes de deitar']]}],ori:['CONTROLE DE ESTÍMULOS: ir para a cama só com sono; se não dormir em ~20 min, levantar e fazer algo relaxante com luz baixa até ter sono; cama só para dormir/sexo (sem TV/celular/trabalho); acordar no MESMO horário todos os dias (inclusive fins de semana); evitar cochilos > 20–30 min e após 15 h','HIGIENE DO SONO: sem cafeína após 14 h, sem álcool como "indutor" (fragmenta o sono), sem nicotina à noite, jantar leve 2–3 h antes, exercício regular (não nas 3 h antes de dormir), quarto escuro/silencioso/fresco (18–22 °C), desligar telas 1 h antes (luz azul), rotina de relaxamento (banho morno, leitura, respiração 4-7-8), exposição à luz solar pela manhã','RESTRIÇÃO DE SONO (TCC-I): limitar o tempo na cama ao tempo realmente dormido (mín. 5 h) e ir ampliando 15 min/semana conforme eficiência > 85%; diário do sono; aplicativos de TCC-I (CBT-i Coach, Sleepio)','Hipnótico: só por semanas, em dias alternados/"quando necessário", nunca aumentar a dose por conta própria; alertar sobre dirigir/operar máquinas; ao suspender, reduzir gradualmente','Retorno em 2–4 semanas; insônia > 3 meses ou com sonolência diurna/ronco/paradas respiratórias → polissonografia / medicina do sono; tratar depressão/ansiedade'],al:['Sonolência diurna intensa, ronco alto com pausas respiratórias, cefaleia matinal (apneia do sono — não sedar)','Noites sem dormir com energia aumentada, fala rápida, gastos/impulsividade (mania — psiquiatria urgente)','Pensamentos de morte/suicídio, desesperança, perda de prazer (depressão)','Sonambulismo, comportamentos complexos (dirigir, comer) sem memória após zolpidem — suspender','Confusão, quedas, alteração de memória em idosos com hipnóticos'],ref:'AASM Clinical Practice Guideline — Insomnia 2017 (Sateia) e Behavioral Treatments 2021 (Edinger); ACP 2016 (Qaseem — TCC-I 1ª linha); European Insomnia Guideline 2023 (Riemann); Cochrane 2018 (BZD/Z-drugs em idosos); AGS Beers Criteria 2023; ABS — Consenso Brasileiro de Insônia 2023.'},
{n:'Síndrome de abstinência alcoólica',cid:'F10.3',sp:'Psiquiatria',ps:[{v:'VO / EV / IM',i:['Início 6–24 h após a última dose (tremor, sudorese, taquicardia, HAS, ansiedade, náusea, insônia); convulsões 6–48 h; alucinose 12–24 h; DELIRIUM TREMENS 48–96 h (confusão, agitação, alucinações, febre, hiperautonomia — mortalidade 1–5% tratado) — avaliar com CIWA-Ar (leve < 10, moderada 10–18, grave ≥ 19) a cada 1–4 h','TIAMINA 300 mg (100 mg × 3 ampolas) EV/IM ANTES de qualquer glicose — repetir 300 mg/dia por 3–5 dias (Wernicke: tríade confusão + ataxia + oftalmoplegia → 500 mg EV 8/8 h por 3 dias); ácido fólico 5 mg VO; glicose 50% só após tiamina se hipoglicemia; SF/RL 1–2 L se desidratado; repor K, Mg (sulfato de Mg 2 g EV se < 1,8 — ↓ arritmia/convulsão)','BENZODIAZEPÍNICO é o tratamento (↓ convulsão e DT): DIAZEPAM 10–20 mg VO (ou 5–10 mg EV lento) a cada 1 h até CIWA < 10 / sedação leve ("sintoma-guiado" — menos BZD total e menor internação que esquema fixo); carga típica 40–100 mg no 1º dia; hepatopatia grave/idoso → lorazepam 2–4 mg VO (sem metabólito ativo); DT/agitação intensa → diazepam EV 10 mg a cada 5–10 min (até 100–200 mg), UTI, fenobarbital 10–15 mg/kg ou propofol/dexmedetomidina se refratário','NÃO usar haloperidol isolado para agitação da abstinência (↓ limiar convulsivo, não trata DT); pode associar haloperidol 2,5–5 mg IM só para alucinações após BZD adequado; evitar fenitoína (não previne convulsão da abstinência) e clorpromazina; carbamazepina/gabapentina são alternativas em leve/moderada ambulatorial sem risco de DT','Exames: glicemia, eletrólitos (Na, K, Mg, P), hemograma, TGO/TGP/GGT, bilirrubina, INR, amilase, CK, ECG (QTc), tóxicos; TC de crânio se TCE, déficit focal, convulsão nova, confusão desproporcional; RX de tórax se febre (aspiração)','INTERNAR: CIWA ≥ 15–19, história de DT ou convulsão por abstinência, convulsão atual, > 60 anos, comorbidade descompensada (cirrose, IC, pneumonia, pancreatite), sem suporte domiciliar, gestante, dependência de BZD/opioide associada, falha ambulatorial; AMBULATORIAL: CIWA < 10–15, sem história de DT/convulsão, suporte familiar, sem comorbidade grave, retorno diário','Infecção, pancreatite, hemorragia digestiva, hepatite alcoólica, hiponatremia (corrigir devagar — mielinólise) e TCE são frequentemente a causa da descompensação — tratar']}],casa:[{v:'USO ORAL (abstinência LEVE/MODERADA, sem história de DT/convulsão, com supervisão familiar e retorno em 24–48 h)',i:[['Diazepam 10 mg (ou clordiazepóxido 25 mg)','20 comprimidos (receita B1)','Dia 1: 1 comprimido de 6/6 h (4/dia); Dia 2: 1 cp de 8/8 h (3/dia); Dia 3: 1 cp de 12/12 h; Dia 4: 1 cp à noite; Dia 5: parar. Tomar 1 cp extra (máx. 2/dia) se tremor/sudorese intensa. Entregar à família para administrar; NÃO beber álcool com a medicação (depressão respiratória)'],['OU Lorazepam 2 mg (hepatopata/idoso)','16 comprimidos (B1)','Dia 1–2: 1 cp de 6/6 h; Dia 3: 1 cp de 8/8 h; Dia 4: 1 cp de 12/12 h; Dia 5: 1 à noite; parar'],['OU Gabapentina 300 mg (alternativa sem BZD — leve/moderada)','40 cápsulas','Dia 1–3: 1 cápsula de 8/8 h (600 mg à noite se insônia); dias 4–7: 1 de 12/12 h; depois pode manter 300–600 mg 8/8 h como anticraving'],['Tiamina (vitamina B1) 300 mg','30 comprimidos','Tomar 1 comprimido 1×/dia por 30 dias (ou 100 mg 8/8 h)'],['Ácido fólico 5 mg','30 comprimidos','Tomar 1 comprimido 1×/dia por 30 dias'],['Complexo B','30 comprimidos','Tomar 1 comprimido 1×/dia'],['Omeprazol 20 mg','30 cápsulas','Tomar 1 cápsula em jejum por 30 dias (gastrite alcoólica)'],['Naltrexona 50 mg (após desintoxicação — anticraving, ↓ recaída; não com opioides; checar TGO/TGP) — ou acamprosato 666 mg 8/8 h','30 comprimidos','Tomar 1 comprimido 1×/dia por ≥ 3–6 meses, com acompanhamento no CAPS-AD']]}],ori:['Não ficar sozinho nos primeiros 3–5 dias; familiar administra a medicação e observa: confusão, tremor intenso, alucinações, febre, convulsão → PS imediatamente (delirium tremens pode ser fatal)','Hidratação (2–3 L/dia), alimentação regular (hipoglicemia), repouso; evitar cafeína em excesso; não dirigir nem operar máquinas durante o uso do benzodiazepínico','NÃO retomar o álcool "para aliviar" — piora o ciclo; não combinar álcool com a medicação (pode parar de respirar)','Encaminhar ao CAPS-AD (sem agendamento) / UBS em ≤ 48–72 h: plano de tratamento, anticraving (naltrexona/acamprosato/topiramato/dissulfiram), grupos (AA — 24 h), psicoterapia; tratar depressão/ansiedade; abordar tabagismo','Exames de seguimento: função hepática, hemograma, USG de abdome (cirrose/pancreatite), sorologias (hepatites B/C, HIV, sífilis), vacinação (hepatite B, influenza, pneumocócica)'],al:['Confusão mental, desorientação, alucinações (ver insetos/animais), agitação intensa, febre, sudorese profusa, taquicardia > 120 (delirium tremens — EMERGÊNCIA, UTI)','Convulsão (mesmo única), desmaio, vômitos com sangue ou fezes pretas (hemorragia digestiva), icterícia, dor abdominal intensa (pancreatite), confusão + desequilíbrio + visão dupla (Wernicke)','Sonolência excessiva, respiração lenta (excesso de benzodiazepínico ± álcool)','Pensamentos suicidas (risco ↑ na abstinência)'],ref:'ASAM Clinical Practice Guideline on Alcohol Withdrawal Management 2020; Cochrane 2010 (BZD — Amato) e 2011 (anticonvulsivantes); Saitz JAMA 1994 (sintoma-guiado CIWA); NICE CG100/CG115; Thomson Alcohol Alcohol 2002 (tiamina/Wernicke — EFNS 2010); ABP/ABEAD; Mayo-Smith JAMA 1997 (meta-análise).'},
/* ===== ENDÓCRINO / METABÓLICO ===== */
{n:'Hipoglicemia',cid:'E16.2 / E11.6',sp:'Endocrinologia',ps:[{v:'VO / EV / IM',i:['Glicemia capilar < 70 mg/dL (nível 1), < 54 (nível 2), ou qualquer valor com alteração de consciência/necessidade de ajuda (nível 3) — tratar imediatamente; se glicosímetro indisponível e suspeita: tratar','CONSCIENTE e deglutindo: 15–20 g de carboidrato de absorção rápida VO (3–4 sachês/colheres de açúcar em água, 150 mL de suco de laranja/refrigerante comum, 3–4 balas de glicose, 1 colher de sopa de mel) → remedir em 15 min → repetir se < 70 ("regra dos 15") → depois lanche com carboidrato complexo + proteína se próxima refeição > 1 h','INCONSCIENTE/convulsão/incapaz de deglutir: GLICOSE 50% 30–50 mL EV (15–25 g; ou glicose 25%/10% 100–250 mL — menos flebite) em bolus, repetir em 5–10 min se < 70; sem acesso: GLUCAGON 1 mg IM/SC (ou 3 mg intranasal) — eficaz em 10–15 min (menos em hepatopata/etilista/jejum prolongado — depletado de glicogênio); nunca dar açúcar/mel na boca de inconsciente (aspiração)','ETILISTA/DESNUTRIDO: TIAMINA 100–300 mg EV ANTES ou junto da glicose (Wernicke)','SULFONILUREIA (glibenclamida/gliclazida — hipoglicemia prolongada 24–72 h) ou INSULINA DE AÇÃO LONGA/ALTA DOSE: manter glicose 10% EV contínua 50–100 mL/h e observar 24 h (internar); octreotida 50–100 mcg SC 8/8 h bloqueia a liberação de insulina pela sulfonilureia (evidência moderada) — reduz recorrência','Glicemia a cada 15 min até > 100 estável, depois 1/1 h por 4–6 h; alimentar; procurar a CAUSA: dose errada/insulina sem comer, jejum, exercício, álcool, insuficiência renal (acumula sulfonilureia/insulina), hepática, adrenal, sepse, hipoglicemia factícia, insulinoma (sem diabetes — dosar insulina/peptídeo C/sulfonilureia na crise)','Alta se: glicemia > 100 estável por 2–4 h após alimentar, consciente, causa identificada e reversível (insulina rápida/jejum), acompanhante, orientações; NÃO dar alta em sulfonilureia, insulina longa em dose excessiva, hipoglicemia sem causa, recorrente, idoso frágil, DRC, sem suporte']}],casa:[{v:'USO ORAL / SC',i:[['Glicose em gel 15 g (ou sachês/tabletes de glicose; ou 1 colher de sopa de açúcar) — ter sempre consigo','5 sachês','Ao sentir tremor, suor frio, fome, palpitação, confusão: medir a glicemia; se < 70 (ou sem glicosímetro), tomar 15 g de açúcar rápido; medir em 15 min e repetir se continuar < 70; depois comer um lanche'],['Glucagon 1 mg kit (IM/SC) ou 3 mg intranasal (Baqsimi®) — para familiar aplicar se desmaiar','1 kit','Familiar aplica no braço/coxa/glúteo se o paciente estiver inconsciente ou não conseguir engolir; virar de lado; chamar o SAMU 192; dar açúcar quando acordar'],['AJUSTE DO TRATAMENTO DO DIABETES — modelo: reduzir a insulina basal em 10–20% (ex.: de 30 para 24–26 UI); suspender/reduzir sulfonilureia (glibenclamida) — preferir metformina/iDPP4/iSGLT2 (não causam hipoglicemia); revisar insulina prandial (contagem de carboidrato, não aplicar sem comer)','—','Conforme orientação; levar a anotação das glicemias ao retorno em 1 semana']]}],ori:['Carregar sempre açúcar/glicose e identificação de "diabético em uso de insulina"; nunca pular refeições após aplicar insulina/tomar sulfonilureia; comer antes de dirigir e a cada 2 h em viagens; checar a glicemia antes de dirigir (> 90)','Álcool: nunca em jejum, sempre com comida, limitar; pode causar hipoglicemia até 12–24 h depois (bloqueia a produção hepática de glicose) e mascarar sintomas','Exercício: reduzir insulina/comer carboidrato antes; hipoglicemia pode ocorrer horas depois (noturna)','Hipoglicemias repetidas levam a "hipoglicemia assintomática" (perda dos sinais de alerta): relaxar as metas por semanas; monitorização contínua (sensor) se disponível; ensinar família a reconhecer e tratar','Retorno em 1 semana com endocrinologia/UBS para ajuste; se DRC/idoso: metas menos rígidas (HbA1c 7,5–8,5%) e evitar sulfonilureia/insulina complexa'],al:['Nova hipoglicemia com perda de consciência, convulsão, ou que não melhora com açúcar → SAMU 192','Hipoglicemias frequentes (> 2/semana), noturnas (pesadelos, sudorese, cefaleia matinal), ou sem sintomas de alerta','Confusão persistente após correção (edema cerebral, AVC, outra causa), vômitos impedindo comer','Hipoglicemia em quem NÃO usa insulina/sulfonilureia (investigar)'],ref:'ADA Standards of Care 2024 (seção 6 — Glycemic Goals and Hypoglycemia); SBD — Diretriz 2023/2024 (Hipoglicemia); Endocrine Society 2009/2023 (Cryer; hipoglicemia em adultos não diabéticos); AHA/ILCOR; Cochrane 2019 (glucagon intranasal); Glatstein Pharmacotherapy 2012 (octreotida/sulfonilureia); Wilson EM Clin 2019.'},
{n:'Hiperglicemia sem cetoacidose / diabetes descompensado',cid:'E11.65 / R73.9',sp:'Endocrinologia',ps:[{v:'VO / EV / SC',i:['Glicemia > 250–300 mg/dL: EXCLUIR CETOACIDOSE (cetonemia/cetonúria, gasometria pH < 7,30, HCO₃ < 18, ânion gap > 12) e ESTADO HIPERGLICÊMICO HIPEROSMOLAR (glicemia > 600, osmolaridade > 320, confusão/coma, sem cetose importante) → se presentes: protocolo próprio (SF 15–20 mL/kg/h na 1ª h, insulina regular 0,1 U/kg/h EV após K > 3,3, reposição de K, internar/UTI)','Hiperglicemia simples (sem cetose/acidose, consciente, tolerando VO): hidratação (VO ou SF 0,9% 500–1000 mL EV em 1–2 h se desidratado/vômitos), tratar o fator precipitante (infecção — urina I, RX, hemograma; IAM — ECG; AVC; corticoide; má adesão; álcool; medicação nova) e corrigir com INSULINA REGULAR/RÁPIDA SC: 0,1 U/kg (ou escala: 250–300 → 4 U; 300–350 → 6 U; 350–400 → 8 U; > 400 → 10 U) SC; remedir em 2 h; glicemia de alta idealmente < 250–300 e caindo','Não é necessário "zerar" a glicemia no PS; evitar insulina EV em bolus sem CAD; evitar hidratação excessiva em cardiopata/renal','Exames: glicemia, eletrólitos (Na corrigido: +1,6 para cada 100 mg/dL acima de 100), creatinina/ureia, cetonas, gasometria venosa se cetonúria/mal-estar, hemograma, urina I/urocultura, ECG (> 40 a), HbA1c (orienta ajuste)','Diabetes NOVO: tipo 1 provável (jovem, magro, perda de peso, cetose, sintomas < semanas) → INSULINA desde o início (basal 0,2–0,3 U/kg + prandial), endocrino em ≤ 1 semana, não dar alta só com metformina; tipo 2 sintomático (polis + glicemia > 300 ou HbA1c > 10%) → iniciar insulina basal (NPH 10 U ou 0,1–0,2 U/kg à noite) + metformina','INTERNAR: CAD/EHH, vômitos persistentes, incapacidade de hidratar VO, infecção grave/sepse, IAM/AVC, IRA, DM1 novo sem retaguarda rápida, idoso frágil confuso, gestante com descompensação']}],casa:[{v:'USO ORAL / SC',i:[['Metformina 500 mg (ou 850 mg) — iniciar/manter (se TFG > 30; não se vômitos/desidratação/contraste nos próximos dias)','60 comprimidos','Tomar 1 comprimido no jantar por 1 semana, depois 1 no café e 1 no jantar (aumentar até 2 g/dia conforme tolerância, com as refeições); suspender se vômitos/diarreia intensos'],['Insulina NPH 100 UI/mL (frasco 10 mL ou caneta 3 mL) — se glicemia > 300, HbA1c > 10%, sintomas ou DM1','1 frasco/2 canetas + seringas 1 mL (ou agulhas 4–6 mm) + lancetas/tiras','Aplicar 10 UI (0,1–0,2 U/kg) SC às 22 h (bedtime); aumentar 2 UI a cada 3 dias se glicemia de jejum > 130 (reduzir 4 UI se < 70); rodízio de locais (abdome, coxa, braço)'],['Insulina Regular 100 UI/mL (correção prandial — se DM1 ou hiperglicemia pós-prandial > 250)','1 frasco','Aplicar SC 30 min antes das refeições: 4 UI se glicemia 200–250; 6 UI se 250–300; 8 UI se 300–350; 10 UI se > 350 (ajustar na consulta); DM1: 0,1–0,2 U/kg/refeição'],['Gliclazida MR 30–60 mg (alternativa oral se não aceitar insulina, sem risco de hipoglicemia grave — evitar glibenclamida)','30 comprimidos','Tomar 1 comprimido no café da manhã'],['Dapagliflozina 10 mg ou Empagliflozina 10 mg (se DCV/IC/DRC — não iniciar na descompensação aguda/cetose/infecção genital)','30 comprimidos','Tomar 1 comprimido pela manhã (quando estável)'],['Tiras reagentes + glicosímetro (SUS — Lei 11.347)','100 tiras','Medir a glicemia em jejum e antes do jantar (4×/dia se insulina prandial) e anotar; trazer no retorno']]}],ori:['Hidratação 2–3 L de água/dia (sem açúcar); evitar refrigerante, suco, doces, pão branco, massas em excesso; refeições regulares com fibras/proteína; não ficar em jejum prolongado usando insulina','Sinais de CETOACIDOSE para procurar PS: náuseas/vômitos, dor abdominal, respiração rápida/profunda, hálito de "acetona"/frutas, sonolência, glicemia > 300 persistente com mal-estar — medir cetona se tiver tira','Dias de doença (infecção/febre): NÃO suspender a insulina basal (pode até precisar de mais); medir glicemia a cada 4 h; hidratar; suspender metformina/iSGLT2 se vomitando; procurar atendimento se > 300 por mais de 12 h ou vômitos','Técnica de insulina (aplicação, rodízio, conservação na geladeira 2–8 °C, caneta em uso até 28–30 dias em temperatura ambiente); descarte seguro de agulhas; carregar açúcar (risco de hipoglicemia)','Retorno em 7 dias na UBS/endocrino com as glicemias anotadas; exames: HbA1c, perfil lipídico, creatinina/albuminúria, fundo de olho, pés; vacinas; atividade física 150 min/semana após liberação; cessar tabagismo; iniciar estatina se > 40 anos'],al:['Vômitos, dor abdominal, respiração ofegante, hálito cetônico, sonolência/confusão, glicemia "HI"/> 500 → PS (cetoacidose/hiperosmolar)','Febre, ferida no pé que não cicatriza, dor para urinar (infecção descompensa)','Hipoglicemia (< 70) com o novo tratamento: tratar e reduzir dose; tontura, visão turva súbita','Sede/urina excessivas persistentes apesar do tratamento após 1 semana'],ref:'ADA Standards of Care 2024 (seções 9 e 16 — hyperglycemic crises); Umpierrez/Kitabchi Diabetes Care 2009 e 2024 (Consenso Crises Hiperglicêmicas — ADA/EASD/JBDS/AACE/DTS); SBD — Diretriz 2023/2024 (Manejo da hiperglicemia no PS; insulinização no DM2); JBDS-IP 2023; Cochrane 2016 (insulina SC vs EV em CAD leve).'}
);
